/* HUD Sci-Fi — cool dark blue, thin cyan lines, corner brackets, radar data */
.theme-hud-scifi {
  --bg: oklch(0.170 0.017 252.7);
  --surface: oklch(0.201 0.024 251.6);
  --surface-2: oklch(0.239 0.032 252.9);
  --fg: oklch(0.922 0.025 240.7);
  --fg-muted: oklch(0.620 0.050 244.7);
  --accent: oklch(0.806 0.129 212.2);
  --accent-fg: oklch(0.173 0.027 233.6);
  --accent-2: oklch(0.623 0.200 265.8);
  --line: oklch(0.75 0.1 220 / 30%);
  --success: oklch(0.845 0.198 153.3);
  --warning: oklch(0.839 0.152 90.4);
  --danger: oklch(0.650 0.199 29.8);
  --radius: 2px;
  --radius-sm: 1px;
  --radius-lg: 3px;
  --radius-pill: 3px;
  --shadow-1: 0 0 12px oklch(0.75 0.12 220 / 15%);
  --shadow-2: 0 0 24px oklch(0.75 0.12 220 / 20%);
  --shadow-3: 0 0 48px oklch(0.75 0.12 220 / 25%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 50%, transparent), 0 0 16px color-mix(in oklab, var(--accent) 30%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Rajdhani", sans-serif;
  --font-body: "Rajdhani", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.06em;
  --label-transform: uppercase;
  --label-tracking: 0.22em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-hud-scifi h1,
.theme-hud-scifi h2,
.theme-hud-scifi h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}
.theme-hud-scifi h1, .theme-hud-scifi h2, .theme-hud-scifi h3 { text-transform: uppercase; }

/* signature */
.theme-hud-scifi { --font-ui: var(--font-display); background-image: repeating-linear-gradient(0deg, transparent 0 3px, oklch(0.75 0.1 220 / 4%) 3px 4px); }
.theme-hud-scifi h1, .theme-hud-scifi h2 { text-shadow: 0 0 12px color-mix(in oklab, var(--accent) 60%, transparent); }
.theme-hud-scifi button { clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px); text-transform: uppercase; letter-spacing: 0.14em; }

/* alt mode: auto-derived light variant */
.theme-hud-scifi.alt-mode {
  --bg: oklch(0.98 0.012 252.7);
  --surface: oklch(0.955 0.015 252.7);
  --surface-2: oklch(0.92 0.017 252.7);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --accent: oklch(0.52 0.129 212.2);
  --accent-fg: oklch(1 0 0);
  background-image: none;
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
